import{_ as o,o as r,c as a,aj as l}from"./chunks/framework.DpVzuYkC.js";const g=JSON.parse('{"title":"Woodpecker Server 环境变量参考","description":"","frontmatter":{},"headers":[],"relativePath":"woodpecker/server-env.md","filePath":"woodpecker/server-env.md"}'),i={name:"woodpecker/server-env.md"};function t(s,e,n,d,c,E){return r(),a("div",null,[...e[0]||(e[0]=[l(`<h1 id="woodpecker-server-环境变量参考" tabindex="-1">Woodpecker Server 环境变量参考 <a class="header-anchor" href="#woodpecker-server-环境变量参考" aria-label="Permalink to “Woodpecker Server 环境变量参考”">​</a></h1><blockquote><p>本文档基于 <a href="https://woodpecker-ci.org/docs/administration/configuration/server" target="_blank" rel="noreferrer">Woodpecker 官方文档 - Server 配置</a> 整理，涵盖了 Woodpecker Server 端的所有环境变量配置项。</p></blockquote><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to “目录”">​</a></h2><ul><li><a href="#通用日志">通用日志</a></li><li><a href="#数据库">数据库</a></li><li><a href="#服务器网络">服务器网络</a></li><li><a href="#tlsssl">TLS/SSL</a></li><li><a href="#grpc">gRPC</a></li><li><a href="#监控指标-prometheus">监控指标 (Prometheus)</a></li><li><a href="#ui-自定义">UI 自定义</a></li><li><a href="#用户与认证">用户与认证</a></li><li><a href="#仓库">仓库</a></li><li><a href="#pipeline-设置">Pipeline 设置</a></li><li><a href="#插件">插件</a></li><li><a href="#docker">Docker</a></li><li><a href="#agent-通信">Agent 通信</a></li><li><a href="#状态推送">状态推送</a></li><li><a href="#配置扩展">配置扩展</a></li><li><a href="#密钥扩展">密钥扩展</a></li><li><a href="#注册表扩展">注册表扩展</a></li><li><a href="#扩展网络限制">扩展网络限制</a></li><li><a href="#forge-相关">Forge 相关</a></li><li><a href="#其他">其他</a></li><li><a href="#forge-专属变量">Forge 专属变量</a></li></ul><hr><h2 id="通用日志" tabindex="-1">通用日志 <a class="header-anchor" href="#通用日志" aria-label="Permalink to “通用日志”">​</a></h2><h3 id="woodpecker-log-level" tabindex="-1">WOODPECKER_LOG_LEVEL <a class="header-anchor" href="#woodpecker-log-level" aria-label="Permalink to “WOODPECKER_LOG_LEVEL”">​</a></h3><ul><li><strong>默认值</strong>: <code>info</code></li><li><strong>说明</strong>: 配置日志级别。可选值：<code>trace</code>、<code>debug</code>、<code>info</code>、<code>warn</code>、<code>error</code>、<code>fatal</code>、<code>panic</code>、<code>disabled</code>、空字符串。</li></ul><h3 id="woodpecker-log-file" tabindex="-1">WOODPECKER_LOG_FILE <a class="header-anchor" href="#woodpecker-log-file" aria-label="Permalink to “WOODPECKER_LOG_FILE”">​</a></h3><ul><li><strong>默认值</strong>: <code>stderr</code></li><li><strong>说明</strong>: 日志输出目标。可使用 <code>stdout</code> 和 <code>stderr</code> 作为特殊关键词。</li></ul><h3 id="woodpecker-database-log" tabindex="-1">WOODPECKER_DATABASE_LOG <a class="header-anchor" href="#woodpecker-database-log" aria-label="Permalink to “WOODPECKER_DATABASE_LOG”">​</a></h3><ul><li><strong>默认值</strong>: <code>false</code></li><li><strong>说明</strong>: 启用数据库引擎日志（当前为 xorm）。</li></ul><h3 id="woodpecker-database-log-sql" tabindex="-1">WOODPECKER_DATABASE_LOG_SQL <a class="header-anchor" href="#woodpecker-database-log-sql" aria-label="Permalink to “WOODPECKER_DATABASE_LOG_SQL”">​</a></h3><ul><li><strong>默认值</strong>: <code>false</code></li><li><strong>说明</strong>: 启用 SQL 命令日志。</li></ul><h3 id="woodpecker-debug-pretty" tabindex="-1">WOODPECKER_DEBUG_PRETTY <a class="header-anchor" href="#woodpecker-debug-pretty" aria-label="Permalink to “WOODPECKER_DEBUG_PRETTY”">​</a></h3><ul><li><strong>默认值</strong>: <code>false</code></li><li><strong>说明</strong>: 启用格式化输出调试信息。</li></ul><h3 id="woodpecker-debug-nocolor" tabindex="-1">WOODPECKER_DEBUG_NOCOLOR <a class="header-anchor" href="#woodpecker-debug-nocolor" aria-label="Permalink to “WOODPECKER_DEBUG_NOCOLOR”">​</a></h3><ul><li><strong>默认值</strong>: <code>true</code></li><li><strong>说明</strong>: 禁用彩色调试输出。</li></ul><hr><h2 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to “数据库”">​</a></h2><h3 id="woodpecker-database-driver" tabindex="-1">WOODPECKER_DATABASE_DRIVER <a class="header-anchor" href="#woodpecker-database-driver" aria-label="Permalink to “WOODPECKER_DATABASE_DRIVER”">​</a></h3><ul><li><strong>默认值</strong>: <code>sqlite3</code></li><li><strong>说明</strong>: 数据库驱动名称。可选值：<code>sqlite3</code>、<code>mysql</code>、<code>postgres</code>。</li></ul><h3 id="woodpecker-database-datasource" tabindex="-1">WOODPECKER_DATABASE_DATASOURCE <a class="header-anchor" href="#woodpecker-database-datasource" aria-label="Permalink to “WOODPECKER_DATABASE_DATASOURCE”">​</a></h3><ul><li><strong>默认值</strong>: <code>woodpecker.sqlite</code>（非容器环境）/ <code>/var/lib/woodpecker/woodpecker.sqlite</code>（容器环境）</li><li><strong>说明</strong>: 数据库连接字符串。</li><li><strong>示例</strong>:<div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># MySQL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WOODPECKER_DATABASE_DATASOURCE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">root:password@tcp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1.2.3.4:3306</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/woodpecker?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">parseTime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># PostgreSQL (要求版本 &gt;= 11)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WOODPECKER_DATABASE_DATASOURCE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">postgres://root:password@1.2.3.4:5432/woodpecker?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sslmode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">disable</span></span></code></pre></div></li></ul><h3 id="woodpecker-database-datasource-file" tabindex="-1">WOODPECKER_DATABASE_DATASOURCE_FILE <a class="header-anchor" href="#woodpecker-database-datasource-file" aria-label="Permalink to “WOODPECKER_DATABASE_DATASOURCE_FILE”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 从指定文件路径读取 <code>WOODPECKER_DATABASE_DATASOURCE</code> 的值。</li></ul><h3 id="woodpecker-database-max-connections" tabindex="-1">WOODPECKER_DATABASE_MAX_CONNECTIONS <a class="header-anchor" href="#woodpecker-database-max-connections" aria-label="Permalink to “WOODPECKER_DATABASE_MAX_CONNECTIONS”">​</a></h3><ul><li><strong>默认值</strong>: <code>100</code></li><li><strong>说明</strong>: xorm 允许创建的最大数据库连接数。</li></ul><h3 id="woodpecker-database-idle-connections" tabindex="-1">WOODPECKER_DATABASE_IDLE_CONNECTIONS <a class="header-anchor" href="#woodpecker-database-idle-connections" aria-label="Permalink to “WOODPECKER_DATABASE_IDLE_CONNECTIONS”">​</a></h3><ul><li><strong>默认值</strong>: <code>2</code></li><li><strong>说明</strong>: xorm 保持打开的空闲数据库连接数。</li></ul><h3 id="woodpecker-database-connection-timeout" tabindex="-1">WOODPECKER_DATABASE_CONNECTION_TIMEOUT <a class="header-anchor" href="#woodpecker-database-connection-timeout" aria-label="Permalink to “WOODPECKER_DATABASE_CONNECTION_TIMEOUT”">​</a></h3><ul><li><strong>默认值</strong>: <code>3</code> 秒</li><li><strong>说明</strong>: 活跃数据库连接允许保持打开的时间。</li></ul><blockquote><p><strong>注意</strong>: 默认数据库引擎为嵌入式 SQLite，无需额外安装配置。若使用 MySQL/MariaDB 或 PostgreSQL，需手动创建数据库（<code>CREATE DATABASE</code>）。Woodpecker 会自动处理数据库迁移（包括初始建表和索引升级），但<strong>不会自动备份数据库</strong>，需使用第三方工具。</p></blockquote><hr><h2 id="服务器网络" tabindex="-1">服务器网络 <a class="header-anchor" href="#服务器网络" aria-label="Permalink to “服务器网络”">​</a></h2><h3 id="woodpecker-host" tabindex="-1">WOODPECKER_HOST <a class="header-anchor" href="#woodpecker-host" aria-label="Permalink to “WOODPECKER_HOST”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 服务器面向用户的完整 URL，包括主机名、端口（若非 HTTP/HTTPS 默认端口）和路径前缀。</li><li><strong>示例</strong>:<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>WOODPECKER_HOST=http://woodpecker.example.org</span></span>
<span class="line"><span>WOODPECKER_HOST=http://example.org/woodpecker</span></span>
<span class="line"><span>WOODPECKER_HOST=http://example.org:1234/woodpecker</span></span></code></pre></div></li></ul><h3 id="woodpecker-server-addr" tabindex="-1">WOODPECKER_SERVER_ADDR <a class="header-anchor" href="#woodpecker-server-addr" aria-label="Permalink to “WOODPECKER_SERVER_ADDR”">​</a></h3><ul><li><strong>默认值</strong>: <code>:8000</code></li><li><strong>说明</strong>: HTTP 监听地址。支持通过 <code>unix://</code> 前缀使用 Unix Socket。</li><li><strong>示例</strong>: <code>unix:///var/run/woodpecker.sock</code></li></ul><h3 id="woodpecker-server-addr-tls" tabindex="-1">WOODPECKER_SERVER_ADDR_TLS <a class="header-anchor" href="#woodpecker-server-addr-tls" aria-label="Permalink to “WOODPECKER_SERVER_ADDR_TLS”">​</a></h3><ul><li><strong>默认值</strong>: <code>:443</code></li><li><strong>说明</strong>: 启用 SSL 时的 HTTPS 监听端口。</li></ul><h3 id="woodpecker-grpc-addr" tabindex="-1">WOODPECKER_GRPC_ADDR <a class="header-anchor" href="#woodpecker-grpc-addr" aria-label="Permalink to “WOODPECKER_GRPC_ADDR”">​</a></h3><ul><li><strong>默认值</strong>: <code>:9000</code></li><li><strong>说明</strong>: gRPC 监听地址。可使用 <code>localhost:9000</code> 或 IP 地址绑定到特定接口。支持 <code>unix://</code> 前缀。</li><li><strong>示例</strong>: <code>unix:///run/woodpecker-grcp.sock</code></li></ul><hr><h2 id="tls-ssl" tabindex="-1">TLS/SSL <a class="header-anchor" href="#tls-ssl" aria-label="Permalink to “TLS/SSL”">​</a></h2><h3 id="woodpecker-server-cert" tabindex="-1">WOODPECKER_SERVER_CERT <a class="header-anchor" href="#woodpecker-server-cert" aria-label="Permalink to “WOODPECKER_SERVER_CERT”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 服务器用于接受 HTTPS 请求的 SSL 证书路径。</li><li><strong>示例</strong>: <code>WOODPECKER_SERVER_CERT=/path/to/cert.pem</code></li></ul><h3 id="woodpecker-server-key" tabindex="-1">WOODPECKER_SERVER_KEY <a class="header-anchor" href="#woodpecker-server-key" aria-label="Permalink to “WOODPECKER_SERVER_KEY”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 服务器用于接受 HTTPS 请求的 SSL 证书密钥路径。</li><li><strong>示例</strong>: <code>WOODPECKER_SERVER_KEY=/path/to/key.pem</code></li></ul><hr><h2 id="grpc" tabindex="-1">gRPC <a class="header-anchor" href="#grpc" aria-label="Permalink to “gRPC”">​</a></h2><h3 id="woodpecker-grpc-secret" tabindex="-1">WOODPECKER_GRPC_SECRET <a class="header-anchor" href="#woodpecker-grpc-secret" aria-label="Permalink to “WOODPECKER_GRPC_SECRET”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 用于签名 gRPC 连接 JWT 的密钥。</li><li><strong>说明</strong>: 若未设置，服务器会生成一个临时密钥，每次重启都会变更。<strong>高可用 (HA) 部署时必须显式设置</strong>，确保多个 Server 副本使用相同密钥。</li><li><strong>生成方法</strong>: <code>openssl rand -hex 32</code></li></ul><h3 id="woodpecker-grpc-secret-file" tabindex="-1">WOODPECKER_GRPC_SECRET_FILE <a class="header-anchor" href="#woodpecker-grpc-secret-file" aria-label="Permalink to “WOODPECKER_GRPC_SECRET_FILE”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 从指定文件路径读取 <code>WOODPECKER_GRPC_SECRET</code> 的值。文件应持久化存储且仅 Woodpecker 服务器可读。</li></ul><hr><h2 id="监控指标-prometheus" tabindex="-1">监控指标 (Prometheus) <a class="header-anchor" href="#监控指标-prometheus" aria-label="Permalink to “监控指标 (Prometheus)”">​</a></h2><h3 id="woodpecker-prometheus-auth-token" tabindex="-1">WOODPECKER_PROMETHEUS_AUTH_TOKEN <a class="header-anchor" href="#woodpecker-prometheus-auth-token" aria-label="Permalink to “WOODPECKER_PROMETHEUS_AUTH_TOKEN”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 保护 Prometheus 指标端点的令牌。<strong>必须设置才能启用 <code>/metrics</code> 端点</strong>。</li></ul><h3 id="woodpecker-prometheus-auth-token-file" tabindex="-1">WOODPECKER_PROMETHEUS_AUTH_TOKEN_FILE <a class="header-anchor" href="#woodpecker-prometheus-auth-token-file" aria-label="Permalink to “WOODPECKER_PROMETHEUS_AUTH_TOKEN_FILE”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 从指定文件路径读取 <code>WOODPECKER_PROMETHEUS_AUTH_TOKEN</code> 的值。</li></ul><h3 id="woodpecker-metrics-server-addr" tabindex="-1">WOODPECKER_METRICS_SERVER_ADDR <a class="header-anchor" href="#woodpecker-metrics-server-addr" aria-label="Permalink to “WOODPECKER_METRICS_SERVER_ADDR”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 配置一个不受保护的 Metrics 端点。值为空时完全禁用 Metrics 端点。</li><li><strong>示例</strong>: <code>:9001</code></li></ul><h3 id="woodpecker-step-level-metrics" tabindex="-1">WOODPECKER_STEP_LEVEL_METRICS <a class="header-anchor" href="#woodpecker-step-level-metrics" aria-label="Permalink to “WOODPECKER_STEP_LEVEL_METRICS”">​</a></h3><ul><li><strong>默认值</strong>: <code>true</code></li><li><strong>说明</strong>: 启用步骤级指标，包括失败步骤计数器和步骤持续时间直方图。</li></ul><hr><h2 id="ui-自定义" tabindex="-1">UI 自定义 <a class="header-anchor" href="#ui-自定义" aria-label="Permalink to “UI 自定义”">​</a></h2><h3 id="woodpecker-custom-css-file" tabindex="-1">WOODPECKER_CUSTOM_CSS_FILE <a class="header-anchor" href="#woodpecker-custom-css-file" aria-label="Permalink to “WOODPECKER_CUSTOM_CSS_FILE”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 自定义 CSS 文件路径，用于定制 UI（横幅消息、Logo、环境提示等）。文件必须为 UTF-8 编码。</li><li><strong>示例</strong>: <code>WOODPECKER_CUSTOM_CSS_FILE=/usr/local/www/woodpecker.css</code></li></ul><h3 id="woodpecker-custom-js-file" tabindex="-1">WOODPECKER_CUSTOM_JS_FILE <a class="header-anchor" href="#woodpecker-custom-js-file" aria-label="Permalink to “WOODPECKER_CUSTOM_JS_FILE”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 自定义 JS 文件路径，用于定制 UI。文件必须为 UTF-8 编码。</li><li><strong>示例</strong>: <code>WOODPECKER_CUSTOM_JS_FILE=/usr/local/www/woodpecker.js</code></li></ul><hr><h2 id="用户与认证" tabindex="-1">用户与认证 <a class="header-anchor" href="#用户与认证" aria-label="Permalink to “用户与认证”">​</a></h2><h3 id="woodpecker-open" tabindex="-1">WOODPECKER_OPEN <a class="header-anchor" href="#woodpecker-open" aria-label="Permalink to “WOODPECKER_OPEN”">​</a></h3><ul><li><strong>默认值</strong>: <code>false</code></li><li><strong>说明</strong>: 是否允许用户注册。默认关闭，用户由 Forge（通过 OAuth2）提供。</li></ul><h3 id="woodpecker-admin" tabindex="-1">WOODPECKER_ADMIN <a class="header-anchor" href="#woodpecker-admin" aria-label="Permalink to “WOODPECKER_ADMIN”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 管理员账号列表（逗号分隔）。</li><li><strong>示例</strong>: <code>WOODPECKER_ADMIN=user1,user2</code></li></ul><h3 id="woodpecker-orgs" tabindex="-1">WOODPECKER_ORGS <a class="header-anchor" href="#woodpecker-orgs" aria-label="Permalink to “WOODPECKER_ORGS”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 允许的组织列表（逗号分隔）。需要配合 <code>WOODPECKER_OPEN=true</code> 使用。</li><li><strong>示例</strong>: <code>WOODPECKER_ORGS=org1,org2</code></li></ul><h3 id="woodpecker-repo-owners" tabindex="-1">WOODPECKER_REPO_OWNERS <a class="header-anchor" href="#woodpecker-repo-owners" aria-label="Permalink to “WOODPECKER_REPO_OWNERS”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 仅同步指定所有者的仓库。通常设置为公司 GitHub 组织名称。</li><li><strong>示例</strong>: <code>WOODPECKER_REPO_OWNERS=my_company,my_company_oss_github_user</code></li></ul><h3 id="woodpecker-authenticate-public-repos" tabindex="-1">WOODPECKER_AUTHENTICATE_PUBLIC_REPOS <a class="header-anchor" href="#woodpecker-authenticate-public-repos" aria-label="Permalink to “WOODPECKER_AUTHENTICATE_PUBLIC_REPOS”">​</a></h3><ul><li><strong>默认值</strong>: <code>false</code></li><li><strong>说明</strong>: 即使仓库是公有的，也始终使用认证来克隆。当 Forge 要求始终认证时使用。</li></ul><h3 id="woodpecker-session-expires" tabindex="-1">WOODPECKER_SESSION_EXPIRES <a class="header-anchor" href="#woodpecker-session-expires" aria-label="Permalink to “WOODPECKER_SESSION_EXPIRES”">​</a></h3><ul><li><strong>默认值</strong>: <code>72h</code></li><li><strong>说明</strong>: 会话过期时间。用户在有效期内无需重新认证即可登录 Woodpecker。</li></ul><hr><h2 id="仓库" tabindex="-1">仓库 <a class="header-anchor" href="#仓库" aria-label="Permalink to “仓库”">​</a></h2><h3 id="woodpecker-async-repository-update" tabindex="-1">WOODPECKER_ASYNC_REPOSITORY_UPDATE <a class="header-anchor" href="#woodpecker-async-repository-update" aria-label="Permalink to “WOODPECKER_ASYNC_REPOSITORY_UPDATE”">​</a></h3><ul><li><strong>默认值</strong>: <code>false</code></li><li><strong>说明</strong>: 启用异步获取用户仓库权限。可显著提升组织有大量 Git 仓库时的登录速度。 <ul><li><strong>禁用</strong>（默认）：用户需等待所有仓库访问信息同步完成，强一致性。</li><li><strong>启用</strong>：用户立即跳转首页，但可能看到过时信息，最终一致性。</li></ul></li></ul><h3 id="woodpecker-default-allow-pull-requests" tabindex="-1">WOODPECKER_DEFAULT_ALLOW_PULL_REQUESTS <a class="header-anchor" href="#woodpecker-default-allow-pull-requests" aria-label="Permalink to “WOODPECKER_DEFAULT_ALLOW_PULL_REQUESTS”">​</a></h3><ul><li><strong>默认值</strong>: <code>true</code></li><li><strong>说明</strong>: 仓库默认是否允许 Pull Request 触发流水线。</li></ul><h3 id="woodpecker-default-approval-mode" tabindex="-1">WOODPECKER_DEFAULT_APPROVAL_MODE <a class="header-anchor" href="#woodpecker-default-approval-mode" aria-label="Permalink to “WOODPECKER_DEFAULT_APPROVAL_MODE”">​</a></h3><ul><li><strong>默认值</strong>: <code>forks</code></li><li><strong>说明</strong>: 仓库默认审批模式。可选值：<code>none</code>、<code>forks</code>、<code>pull_requests</code>、<code>all_events</code>。</li></ul><h3 id="woodpecker-default-cancel-previous-pipeline-events" tabindex="-1">WOODPECKER_DEFAULT_CANCEL_PREVIOUS_PIPELINE_EVENTS <a class="header-anchor" href="#woodpecker-default-cancel-previous-pipeline-events" aria-label="Permalink to “WOODPECKER_DEFAULT_CANCEL_PREVIOUS_PIPELINE_EVENTS”">​</a></h3><ul><li><strong>默认值</strong>: <code>pull_request, push</code></li><li><strong>说明</strong>: 当相同上下文（标签、分支）创建新流水线时，将取消之前流水线的事件列表。</li></ul><h3 id="woodpecker-disable-user-agent-registration" tabindex="-1">WOODPECKER_DISABLE_USER_AGENT_REGISTRATION <a class="header-anchor" href="#woodpecker-disable-user-agent-registration" aria-label="Permalink to “WOODPECKER_DISABLE_USER_AGENT_REGISTRATION”">​</a></h3><ul><li><strong>默认值</strong>: <code>false</code></li><li><strong>说明</strong>: 禁止用户为其拥有管理员权限的仓库创建新 Agent。如果有全局密钥且不信任用户创建恶意 Agent 提取密钥，应启用此选项。</li></ul><hr><h2 id="pipeline-设置" tabindex="-1">Pipeline 设置 <a class="header-anchor" href="#pipeline-设置" aria-label="Permalink to “Pipeline 设置”">​</a></h2><h3 id="woodpecker-default-clone-plugin" tabindex="-1">WOODPECKER_DEFAULT_CLONE_PLUGIN <a class="header-anchor" href="#woodpecker-default-clone-plugin" aria-label="Permalink to “WOODPECKER_DEFAULT_CLONE_PLUGIN”">​</a></h3><ul><li><strong>默认值</strong>: <code>docker.io/woodpeckerci/plugin-git</code></li><li><strong>说明</strong>: 克隆仓库时使用的默认 Docker 镜像。同时会被添加到受信任的克隆插件列表中。</li></ul><h3 id="woodpecker-default-workflow-labels" tabindex="-1">WOODPECKER_DEFAULT_WORKFLOW_LABELS <a class="header-anchor" href="#woodpecker-default-workflow-labels" aria-label="Permalink to “WOODPECKER_DEFAULT_WORKFLOW_LABELS”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 为没有设置标签条件的工作流指定默认标签/平台条件，用于 Agent 选择。</li><li><strong>示例</strong>: <code>platform=linux/amd64,backend=docker</code></li></ul><h3 id="woodpecker-default-pipeline-timeout" tabindex="-1">WOODPECKER_DEFAULT_PIPELINE_TIMEOUT <a class="header-anchor" href="#woodpecker-default-pipeline-timeout" aria-label="Permalink to “WOODPECKER_DEFAULT_PIPELINE_TIMEOUT”">​</a></h3><ul><li><strong>默认值</strong>: <code>60</code> 分钟</li><li><strong>说明</strong>: 仓库流水线默认超时时间（分钟）。</li></ul><h3 id="woodpecker-max-pipeline-timeout" tabindex="-1">WOODPECKER_MAX_PIPELINE_TIMEOUT <a class="header-anchor" href="#woodpecker-max-pipeline-timeout" aria-label="Permalink to “WOODPECKER_MAX_PIPELINE_TIMEOUT”">​</a></h3><ul><li><strong>默认值</strong>: <code>120</code> 分钟</li><li><strong>说明</strong>: 仓库设置中可设置的最大流水线超时时间（分钟）。</li></ul><h3 id="woodpecker-default-pipeline-configs" tabindex="-1">WOODPECKER_DEFAULT_PIPELINE_CONFIGS <a class="header-anchor" href="#woodpecker-default-pipeline-configs" aria-label="Permalink to “WOODPECKER_DEFAULT_PIPELINE_CONFIGS”">​</a></h3><ul><li><strong>默认值</strong>: <code>.woodpecker/</code>, <code>.woodpecker.yaml</code>, <code>.woodpecker.yml</code></li><li><strong>说明</strong>: 默认流水线配置文件路径。</li></ul><h3 id="woodpecker-default-pipeline-config-extensions" tabindex="-1">WOODPECKER_DEFAULT_PIPELINE_CONFIG_EXTENSIONS <a class="header-anchor" href="#woodpecker-default-pipeline-config-extensions" aria-label="Permalink to “WOODPECKER_DEFAULT_PIPELINE_CONFIG_EXTENSIONS”">​</a></h3><ul><li><strong>默认值</strong>: <code>.yaml</code>, <code>.yml</code></li><li><strong>说明</strong>: 扫描流水线配置目录时的默认配置文件扩展名。</li></ul><hr><h2 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to “插件”">​</a></h2><h3 id="woodpecker-plugins-privileged" tabindex="-1">WOODPECKER_PLUGINS_PRIVILEGED <a class="header-anchor" href="#woodpecker-plugins-privileged" aria-label="Permalink to “WOODPECKER_PLUGINS_PRIVILEGED”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 以特权模式运行的 Docker 镜像列表。建议指定镜像标签以确保精确匹配。</li></ul><h3 id="woodpecker-plugins-trusted-clone" tabindex="-1">WOODPECKER_PLUGINS_TRUSTED_CLONE <a class="header-anchor" href="#woodpecker-plugins-trusted-clone" aria-label="Permalink to “WOODPECKER_PLUGINS_TRUSTED_CLONE”">​</a></h3><ul><li><strong>默认值</strong>: <code>docker.io/woodpeckerci/plugin-git,docker.io/woodpeckerci/plugin-git,quay.io/woodpeckerci/plugin-git</code></li><li><strong>说明</strong>: 受信任处理 Git 凭证信息的克隆插件列表。不在列表中的镜像将不会注入 Git 凭证。</li></ul><hr><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to “Docker”">​</a></h2><h3 id="woodpecker-docker-config" tabindex="-1">WOODPECKER_DOCKER_CONFIG <a class="header-anchor" href="#woodpecker-docker-config" aria-label="Permalink to “WOODPECKER_DOCKER_CONFIG”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 为所有流水线配置特定的私有仓库配置。</li><li><strong>示例</strong>: <code>WOODPECKER_DOCKER_CONFIG=/home/user/.docker/config.json</code></li></ul><h3 id="woodpecker-environment" tabindex="-1">WOODPECKER_ENVIRONMENT <a class="header-anchor" href="#woodpecker-environment" aria-label="Permalink to “WOODPECKER_ENVIRONMENT”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 在所有流水线中可用的全局环境变量。不能覆盖已有的内置变量。</li><li><strong>示例</strong>: <code>WOODPECKER_ENVIRONMENT=first_var:value1,second_var:value2</code></li></ul><hr><h2 id="agent-通信" tabindex="-1">Agent 通信 <a class="header-anchor" href="#agent-通信" aria-label="Permalink to “Agent 通信”">​</a></h2><h3 id="woodpecker-agent-secret" tabindex="-1">WOODPECKER_AGENT_SECRET <a class="header-anchor" href="#woodpecker-agent-secret" aria-label="Permalink to “WOODPECKER_AGENT_SECRET”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: Server 和 Agent 之间用于认证通信的共享密钥。可通过 <code>openssl rand -hex 32</code> 生成。</li></ul><h3 id="woodpecker-agent-secret-file" tabindex="-1">WOODPECKER_AGENT_SECRET_FILE <a class="header-anchor" href="#woodpecker-agent-secret-file" aria-label="Permalink to “WOODPECKER_AGENT_SECRET_FILE”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 从指定文件路径读取 <code>WOODPECKER_AGENT_SECRET</code> 的值。</li></ul><h3 id="woodpecker-keepalive-min-time" tabindex="-1">WOODPECKER_KEEPALIVE_MIN_TIME <a class="header-anchor" href="#woodpecker-keepalive-min-time" aria-label="Permalink to “WOODPECKER_KEEPALIVE_MIN_TIME”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 服务端强制策略，规定客户端在发送 keepalive ping 前的最短等待时间。</li><li><strong>示例</strong>: <code>WOODPECKER_KEEPALIVE_MIN_TIME=10s</code></li></ul><hr><h2 id="状态推送" tabindex="-1">状态推送 <a class="header-anchor" href="#状态推送" aria-label="Permalink to “状态推送”">​</a></h2><h3 id="woodpecker-status-context" tabindex="-1">WOODPECKER_STATUS_CONTEXT <a class="header-anchor" href="#woodpecker-status-context" aria-label="Permalink to “WOODPECKER_STATUS_CONTEXT”">​</a></h3><ul><li><strong>默认值</strong>: <code>ci/woodpecker</code></li><li><strong>说明</strong>: Woodpecker 向 SCM 发布状态消息时使用的上下文前缀。运行多个 Woodpecker 实例时可能需要修改。</li></ul><h3 id="woodpecker-status-context-format" tabindex="-1">WOODPECKER_STATUS_CONTEXT_FORMAT <a class="header-anchor" href="#woodpecker-status-context-format" aria-label="Permalink to “WOODPECKER_STATUS_CONTEXT_FORMAT”">​</a></h3><ul><li><strong>默认值</strong>: <code>{{ .context }}/{{ .event }}/{{ .workflow }}{{if not (eq .axis_id 0)}}/{{.axis_id}}{{end}}</code></li><li><strong>说明</strong>: 推送到 Forge 的状态消息模板，使用 Go templates。支持的变量： <ul><li><code>context</code>: Woodpecker 上下文</li><li><code>event</code>: 触发流水线的事件</li><li><code>workflow</code>: 工作流名称</li><li><code>owner</code>: 仓库所有者</li><li><code>repo</code>: 仓库名称</li></ul></li></ul><hr><h2 id="配置扩展" tabindex="-1">配置扩展 <a class="header-anchor" href="#配置扩展" aria-label="Permalink to “配置扩展”">​</a></h2><h3 id="woodpecker-config-extension-endpoint" tabindex="-1">WOODPECKER_CONFIG_EXTENSION_ENDPOINT <a class="header-anchor" href="#woodpecker-config-extension-endpoint" aria-label="Permalink to “WOODPECKER_CONFIG_EXTENSION_ENDPOINT”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 配置扩展端点 URL。详见 <a href="https://woodpecker-ci.org/docs/usage/extensions/config-extension" target="_blank" rel="noreferrer">Configuration Extension</a>。</li></ul><h3 id="woodpecker-default-pipeline-configs-1" tabindex="-1">WOODPECKER_DEFAULT_PIPELINE_CONFIGS <a class="header-anchor" href="#woodpecker-default-pipeline-configs-1" aria-label="Permalink to “WOODPECKER_DEFAULT_PIPELINE_CONFIGS”">​</a></h3><ul><li><strong>默认值</strong>: <code>.woodpecker/</code>, <code>.woodpecker.yaml</code>, <code>.woodpecker.yml</code></li><li><strong>说明</strong>: 默认流水线配置文件路径。</li></ul><h3 id="woodpecker-default-pipeline-config-extensions-1" tabindex="-1">WOODPECKER_DEFAULT_PIPELINE_CONFIG_EXTENSIONS <a class="header-anchor" href="#woodpecker-default-pipeline-config-extensions-1" aria-label="Permalink to “WOODPECKER_DEFAULT_PIPELINE_CONFIG_EXTENSIONS”">​</a></h3><ul><li><strong>默认值</strong>: <code>.yaml</code>, <code>.yml</code></li><li><strong>说明</strong>: 扫描流水线配置目录时的默认配置文件扩展名。</li></ul><h3 id="woodpecker-config-extension-exclusive" tabindex="-1">WOODPECKER_CONFIG_EXTENSION_EXCLUSIVE <a class="header-anchor" href="#woodpecker-config-extension-exclusive" aria-label="Permalink to “WOODPECKER_CONFIG_EXTENSION_EXCLUSIVE”">​</a></h3><ul><li><strong>默认值</strong>: <code>false</code></li><li><strong>说明</strong>: 是否跳过 Forge 请求，全局配置端点独占。</li><li><strong>警告</strong>: 启用后所有仓库将仅使用全局配置服务端点，无法直接在 Forge 中定义流水线。</li></ul><h3 id="woodpecker-config-extension-netrc" tabindex="-1">WOODPECKER_CONFIG_EXTENSION_NETRC <a class="header-anchor" href="#woodpecker-config-extension-netrc" aria-label="Permalink to “WOODPECKER_CONFIG_EXTENSION_NETRC”">​</a></h3><ul><li><strong>默认值</strong>: <code>false</code></li><li><strong>说明</strong>: 将 <code>netrc</code> 数据发送到配置扩展端点。</li><li><strong>警告</strong>: <code>netrc</code> 包含仓库访问凭据，功能强大，请谨慎使用。</li></ul><hr><h2 id="密钥扩展" tabindex="-1">密钥扩展 <a class="header-anchor" href="#密钥扩展" aria-label="Permalink to “密钥扩展”">​</a></h2><h3 id="woodpecker-secret-extension-endpoint" tabindex="-1">WOODPECKER_SECRET_EXTENSION_ENDPOINT <a class="header-anchor" href="#woodpecker-secret-extension-endpoint" aria-label="Permalink to “WOODPECKER_SECRET_EXTENSION_ENDPOINT”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 密钥扩展端点 URL。详见 <a href="https://woodpecker-ci.org/docs/usage/extensions/secret-extension" target="_blank" rel="noreferrer">Secret Extension</a>。</li></ul><h3 id="woodpecker-secret-extension-netrc" tabindex="-1">WOODPECKER_SECRET_EXTENSION_NETRC <a class="header-anchor" href="#woodpecker-secret-extension-netrc" aria-label="Permalink to “WOODPECKER_SECRET_EXTENSION_NETRC”">​</a></h3><ul><li><strong>默认值</strong>: <code>false</code></li><li><strong>说明</strong>: 将 <code>netrc</code> 数据发送到密钥扩展端点。</li></ul><hr><h2 id="注册表扩展" tabindex="-1">注册表扩展 <a class="header-anchor" href="#注册表扩展" aria-label="Permalink to “注册表扩展”">​</a></h2><h3 id="woodpecker-registry-extension-endpoint" tabindex="-1">WOODPECKER_REGISTRY_EXTENSION_ENDPOINT <a class="header-anchor" href="#woodpecker-registry-extension-endpoint" aria-label="Permalink to “WOODPECKER_REGISTRY_EXTENSION_ENDPOINT”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 注册表扩展端点 URL。详见 <a href="https://woodpecker-ci.org/docs/usage/extensions/registry-extension" target="_blank" rel="noreferrer">Registry Extension</a>。</li></ul><h3 id="woodpecker-registry-extension-netrc" tabindex="-1">WOODPECKER_REGISTRY_EXTENSION_NETRC <a class="header-anchor" href="#woodpecker-registry-extension-netrc" aria-label="Permalink to “WOODPECKER_REGISTRY_EXTENSION_NETRC”">​</a></h3><ul><li><strong>默认值</strong>: <code>false</code></li><li><strong>说明</strong>: 将 <code>netrc</code> 数据发送到注册表扩展端点。</li></ul><hr><h2 id="扩展网络限制" tabindex="-1">扩展网络限制 <a class="header-anchor" href="#扩展网络限制" aria-label="Permalink to “扩展网络限制”">​</a></h2><h3 id="woodpecker-extensions-allowed-hosts" tabindex="-1">WOODPECKER_EXTENSIONS_ALLOWED_HOSTS <a class="header-anchor" href="#woodpecker-extensions-allowed-hosts" aria-label="Permalink to “WOODPECKER_EXTENSIONS_ALLOWED_HOSTS”">​</a></h3><ul><li><strong>默认值</strong>: <code>external</code></li><li><strong>说明</strong>: 允许扩展访问的主机列表（逗号分隔）。可选值：<code>loopback</code>、<code>private</code>、<code>external</code>、<code>*</code> 或 CIDR 列表。</li></ul><hr><h2 id="forge-相关" tabindex="-1">Forge 相关 <a class="header-anchor" href="#forge-相关" aria-label="Permalink to “Forge 相关”">​</a></h2><h3 id="woodpecker-forge-timeout" tabindex="-1">WOODPECKER_FORGE_TIMEOUT <a class="header-anchor" href="#woodpecker-forge-timeout" aria-label="Permalink to “WOODPECKER_FORGE_TIMEOUT”">​</a></h3><ul><li><strong>默认值</strong>: <code>5s</code></li><li><strong>说明</strong>: 从 Forge 获取 Woodpecker 配置时的超时时间。语法参考 <a href="https://pkg.go.dev/time#ParseDuration" target="_blank" rel="noreferrer">time.ParseDuration</a>。</li></ul><h3 id="woodpecker-forge-retry" tabindex="-1">WOODPECKER_FORGE_RETRY <a class="header-anchor" href="#woodpecker-forge-retry" aria-label="Permalink to “WOODPECKER_FORGE_RETRY”">​</a></h3><ul><li><strong>默认值</strong>: <code>3</code></li><li><strong>说明</strong>: 从 Forge 获取配置失败时的重试次数。</li></ul><hr><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to “其他”">​</a></h2><h3 id="woodpecker-enable-swagger" tabindex="-1">WOODPECKER_ENABLE_SWAGGER <a class="header-anchor" href="#woodpecker-enable-swagger" aria-label="Permalink to “WOODPECKER_ENABLE_SWAGGER”">​</a></h3><ul><li><strong>默认值</strong>: <code>true</code></li><li><strong>说明</strong>: 启用 Swagger UI 用于 API 文档。</li></ul><h3 id="woodpecker-disable-version-check" tabindex="-1">WOODPECKER_DISABLE_VERSION_CHECK <a class="header-anchor" href="#woodpecker-disable-version-check" aria-label="Permalink to “WOODPECKER_DISABLE_VERSION_CHECK”">​</a></h3><ul><li><strong>默认值</strong>: <code>false</code></li><li><strong>说明</strong>: 在管理 Web UI 中禁用版本检查。</li></ul><h3 id="woodpecker-log-store" tabindex="-1">WOODPECKER_LOG_STORE <a class="header-anchor" href="#woodpecker-log-store" aria-label="Permalink to “WOODPECKER_LOG_STORE”">​</a></h3><ul><li><strong>默认值</strong>: <code>database</code></li><li><strong>说明</strong>: 日志存储方式。可选值： <ul><li><code>database</code>: 日志存储在数据库中</li><li><code>file</code>: 日志以 JSON 文件存储在文件系统中</li><li><code>addon</code>: 使用<a href="./100-addons#log">扩展</a>存储日志</li></ul></li></ul><h3 id="woodpecker-log-store-file-path" tabindex="-1">WOODPECKER_LOG_STORE_FILE_PATH <a class="header-anchor" href="#woodpecker-log-store-file-path" aria-label="Permalink to “WOODPECKER_LOG_STORE_FILE_PATH”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: 根据 <code>WOODPECKER_LOG_STORE</code> 的值： <ul><li><code>file</code>: 日志存储目录</li><li><code>addon</code>: 扩展可执行文件路径</li></ul></li></ul><h3 id="woodpecker-expert-webhook-host" tabindex="-1">WOODPECKER_EXPERT_WEBHOOK_HOST <a class="header-anchor" href="#woodpecker-expert-webhook-host" aria-label="Permalink to “WOODPECKER_EXPERT_WEBHOOK_HOST”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: ⚠️ 专家选项，大部分情况无需设置。Forge 调用 webhook 时使用的完整 Woodpecker 服务器 URL。格式: <code>&lt;scheme&gt;://&lt;host&gt;[/&lt;prefix path&gt;]</code></li></ul><h3 id="woodpecker-expert-forge-oauth-host" tabindex="-1">WOODPECKER_EXPERT_FORGE_OAUTH_HOST <a class="header-anchor" href="#woodpecker-expert-forge-oauth-host" aria-label="Permalink to “WOODPECKER_EXPERT_FORGE_OAUTH_HOST”">​</a></h3><ul><li><strong>默认值</strong>: 无</li><li><strong>说明</strong>: ⚠️ 专家选项，大部分情况无需设置。Forge URL 非公网地址时使用的完整公网 Forge URL。格式: <code>&lt;scheme&gt;://&lt;host&gt;[/&lt;prefix path&gt;]</code></li></ul><h3 id="woodpecker-force-ignore-service-failure" tabindex="-1">WOODPECKER_FORCE_IGNORE_SERVICE_FAILURE <a class="header-anchor" href="#woodpecker-force-ignore-service-failure" aria-label="Permalink to “WOODPECKER_FORCE_IGNORE_SERVICE_FAILURE”">​</a></h3><ul><li><strong>默认值</strong>: <code>true</code></li><li><strong>说明</strong>: ⚠️ 自 v3.14.0 起，Woodpecker 可报告服务和分离步骤的状态。为了向后兼容，默认忽略服务失败。建议禁用此选项并更新流水线配置。</li></ul><hr><h2 id="forge-专属变量" tabindex="-1">Forge 专属变量 <a class="header-anchor" href="#forge-专属变量" aria-label="Permalink to “Forge 专属变量”">​</a></h2><p>各 Forge 平台的专属环境变量配置，请参阅对应的 Forge 配置文档：</p><table tabindex="0"><thead><tr><th>Forge 平台</th><th>文档</th></tr></thead><tbody><tr><td>GitHub</td><td><a href="./README#github">Server 环境变量 - WOODPECKER_GITHUB_*</a></td></tr><tr><td>Gitea</td><td><a href="./README#gitea">Server 环境变量 - WOODPECKER_GITEA_*</a></td></tr><tr><td>Forgejo</td><td><a href="./README#forgejo">Server 环境变量 - WOODPECKER_FORGEJO_*</a></td></tr><tr><td>GitLab</td><td><a href="./README#gitlab">Server 环境变量 - WOODPECKER_GITLAB_*</a></td></tr><tr><td>Bitbucket</td><td><a href="./README#bitbucket">Server 环境变量 - WOODPECKER_BITBUCKET_*</a></td></tr><tr><td>Bitbucket Datacenter</td><td><a href="./README#bitbucket-datacenter-server">Server 环境变量 - WOODPECKER_BITBUCKET_DC_*</a></td></tr><tr><td>AtomGit</td><td><a href="./README#atomgit">Server 环境变量 - WOODPECKER_ATOMGIT_*</a></td></tr></tbody></table>`,192)])])}const O=o(i,[["render",t]]);export{g as __pageData,O as default};
